<template><view class="page"><view class="glass form"><text class="h1">注册</text><input v-model="username" placeholder="用户名"/><input v-model="email" placeholder="邮箱"/><input v-model="password" placeholder="密码" password/><button class="btn" @click="register">注册</button></view></view></template><script setup>import { ref } from 'vue'; import { request } from '../../api/request'; const username=ref(''); const email=ref(''); const password=ref(''); async function register(){await request('/user/register',{method:'POST',data:{username:username.value,email:email.value,password:password.value}}); uni.showToast({title:'注册成功'}); uni.navigateTo({url:'/pages/login/login'})}</script><style scoped>.form{padding:40rpx;margin:80rpx 24rpx}.h1{display:block;font-size:50rpx;font-weight:900;margin-bottom:30rpx}.form input{background:#fff;border-radius:22rpx;padding:22rpx;margin:16rpx 0}</style>
